PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR
VAR CONSTANT
    CAP : INT := 3;
END_VAR

(* Edge detection and occupancy update *)
IF EntrySensor AND NOT PrevEntry THEN
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

(* Update previous sensor states *)
PrevEntry := EntrySensor;
PrevExit := ExitSensor;

(* Full sign logic *)
FullSign := (Count = CAP);

(* Entry barrier logic *)
EntryBarrierOpen := EntryReq AND NOT FullSign;

END_PROGRAM

